/**
 * Issue #278 (owner scope addition, 2026-10-18): durably persist every
 * report generated by a scheduled run so the NextGenTP agent can surface
 * it later.
 *
 * Issue #308 (owner directive, 2026-10-18): ONE canonical copy of each
 * report, max. The generator stores the canonical copy at generation
 * time through the single seam storeReportAtGeneration() — idempotent on
 * the generation id. Every channel (UX render, email, Slack, webhook,
 * HITL dispatch) delivers THAT stored copy; no channel creates a copy,
 * and re-delivery never duplicates the row.
 *
 * Storage: the shared ORM's `mas_reports` table (DO-SQLite, same idiom
 * as mas_events). Each row carries the run/goal identity, a source
 * label, a short summary, and the full report payload as JSON — capped
 * in size so one runaway report cannot blow the 2 MB SQLite row limit.
 *
 * Retrieval: searchScheduledReports() does token-based LIKE matching
 * over title + summary + body, newest first. It is wired into the AI
 * Search agent's search path (src/agents/search.ts, src/agents/mas.ts)
 * behind the same TTL cache as upstream AI Search results, so a
 * report-backed answer is never served stale beyond the cache TTL.
 *
 * Issue #876 (production hotfix, 2026-10-21): the never-throws contract
 * stays, but persistence failures are no longer silent — the persist
 * seams (persistScheduledReportSql, storeReportAtGeneration,
 * recordUsageEvent, the ensure DDL) log the underlying SQL error via
 * console.error before returning null, and ensureScheduledReportsTable
 * reconciles every expected column additively and guards the
 * generation_id UNIQUE INDEX, so accumulated table state (duplicate
 * generation ids, a legacy column shape) can never permanently block
 * report writes for a Durable Object.
 *
 * Issue #338 (design accepted 2026-10-23): the canonical body moves to
 * R2 (reports/<reportId>.json via the REPORTS_BUCKET binding); the
 * mas_reports row keeps the metadata + search fields and gains a
 * body_r2_key pointer (NULL = body still inline). S1 lands the column
 * and the read plumbing only — writes stay inline until S2.
 *
 * This module is SDK-free and never throws into scheduled runs: every
 * public function fails closed to null/[] on bad input or SQL errors.
 */

import type { SqlStorage } from "../orm";
import type { ScheduledReportRecord } from "../types";
import {
  indexCanonicalReport,
  type IndexEnv,
} from "./reportSemanticIndex";

export const SCHEDULED_REPORTS_TABLE = "mas_reports";
/** Body payload cap — keeps every row far under the SQLite row limit. */
export const SCHEDULED_REPORT_MAX_BODY_CHARS = 200_000;
export const SCHEDULED_REPORT_DEFAULT_LIMIT = 5;

export interface ScheduledReportInput {
  /** Run or goal identity, e.g. the scheduled goal id / screen timestamp. */
  runId: string;
  /**
   * Issue #308: generation identity for idempotent storage. When set,
   * storeReportAtGeneration() writes at most one row per generation id —
   * re-delivery, re-posts, and multi-channel sends never duplicate.
   * Scheduled producers use their runId; client-generated reports use a
   * content hash.
   */
  generationId?: string;
  /** Owning user login (#584 EP-003 tenant scoping). Defaults to "default". */
  userLogin?: string;
  /** Human title, e.g. "Autonomous market screen — Technology". */
  title: string;
  /** Producer label: "screener" | "iv_collection" | "retention" | ... */
  source: string;
  /** One-paragraph summary for snippet display. */
  summary: string;
  /** Full report payload (JSON-serializable). */
  body?: unknown;
  /** ISO timestamp; defaults to now. */
  createdAt?: string;
}

/** Add a column to a table when it is missing (additive migration). */
function ensureColumn(
  sql: SqlStorage,
  table: string,
  column: string,
  type: string
): void {
  const cols = Array.from(
    sql.exec(`PRAGMA table_info(${table})`)
  ) as Array<{ name?: unknown }>;
  const names = cols.map((c) => String(c?.name ?? ""));
  if (!names.includes(column)) {
    sql.exec(`ALTER TABLE ${table} ADD COLUMN ${column} ${type}`);
  }
}

/** Idempotent DDL for mas_reports — same shape as the ORM's own block. */
export function ensureScheduledReportsTable(sql: SqlStorage): void {
  sql.exec(`CREATE TABLE IF NOT EXISTS ${SCHEDULED_REPORTS_TABLE} (
    id TEXT PRIMARY KEY,
    run_id TEXT NOT NULL,
    title TEXT NOT NULL,
    source TEXT NOT NULL,
    summary TEXT NOT NULL,
    body TEXT NOT NULL,
    created_at TEXT NOT NULL,
    generation_id TEXT
  )`);
  // Issue #876: reconcile EVERY expected column additively, not just the
  // newest ones. mas_reports has a multi-DDL history (#308, #389, #584),
  // so a DO's table can predate any subset of the current shape; a column
  // the INSERTs name but the table lacks made every persist for that DO
  // fail. Column order in CREATE TABLE above is unchanged — reconciliation
  // only appends what is missing (ALTER cannot add PRIMARY KEY / NOT NULL
  // constraints, so reconciled columns carry the plain TEXT type, exactly
  // as the pre-#876 migrations did for generation_id / user_login).
  ensureColumn(sql, SCHEDULED_REPORTS_TABLE, "id", "TEXT");
  ensureColumn(sql, SCHEDULED_REPORTS_TABLE, "run_id", "TEXT");
  ensureColumn(sql, SCHEDULED_REPORTS_TABLE, "title", "TEXT");
  ensureColumn(sql, SCHEDULED_REPORTS_TABLE, "source", "TEXT");
  ensureColumn(sql, SCHEDULED_REPORTS_TABLE, "summary", "TEXT");
  ensureColumn(sql, SCHEDULED_REPORTS_TABLE, "body", "TEXT");
  ensureColumn(sql, SCHEDULED_REPORTS_TABLE, "created_at", "TEXT");
  // Additive migration for tables created before issue #308.
  ensureColumn(sql, SCHEDULED_REPORTS_TABLE, "generation_id", "TEXT");
  // #584 (EP-003): tenant scoping. Legacy rows predate the column; they were
  // all produced by the single-user deployment, so they backfill to "default"
  // — the same default the routes use when no login is present.
  ensureColumn(sql, SCHEDULED_REPORTS_TABLE, "user_login", "TEXT");
  // Issue #338 (design accepted 2026-10-23): R2-vs-DO storage split for
  // report bodies. body_r2_key is the pointer to the canonical body in R2
  // (reports/<reportId>.json in the REPORTS_BUCKET bucket); NULL means the
  // body still lives inline in the body column (pre-migration rows and,
  // until the S2 write-path slice lands, every new row too).
  ensureColumn(sql, SCHEDULED_REPORTS_TABLE, "body_r2_key", "TEXT");
  try {
    sql.exec(
      `UPDATE ${SCHEDULED_REPORTS_TABLE} SET user_login = ? WHERE user_login IS NULL`,
      "default"
    );
  } catch (err) {
    // Fails closed: a partial backfill is retried on the next call. Issue
    // #876: logged, not silent — a persistently failing backfill is a
    // symptom of the same store trouble the persist seam reports.
    console.error(
      `[scheduledReports] ensureScheduledReportsTable: user_login backfill failed (retried on next call): ${err instanceof Error ? err.message : String(err)}`,
      err
    );
  }
  sql.exec(
    `CREATE INDEX IF NOT EXISTS idx_mas_reports_created ON ${SCHEDULED_REPORTS_TABLE} (created_at DESC)`
  );
  sql.exec(
    `CREATE INDEX IF NOT EXISTS idx_mas_reports_user ON ${SCHEDULED_REPORTS_TABLE} (user_login)`
  );
  // Issue #876: the dedupe index is guarded. Creating a UNIQUE index over
  // a column that already holds duplicate non-null values throws in
  // SQLite; unguarded, that aborted ensure — and therefore EVERY report
  // write for the DO — forever. The duplicates are logged loudly (never
  // deleted here: reconciliation is additive only) and the ensure
  // completes; idempotency for such a DO degrades to the SELECT-then-
  // INSERT check in storeReportAtGeneration until the rows are resolved.
  try {
    sql.exec(
      `CREATE UNIQUE INDEX IF NOT EXISTS idx_mas_reports_generation ON ${SCHEDULED_REPORTS_TABLE} (generation_id)`
    );
  } catch (err) {
    console.error(
      `[scheduledReports] ensureScheduledReportsTable: CREATE UNIQUE INDEX idx_mas_reports_generation failed (duplicate generation_id values already stored?); continuing without it: ${err instanceof Error ? err.message : String(err)}`,
      err
    );
  }
}

/** Shape a report input into a ScheduledReportRecord (id assigned). */
export function toScheduledReportRecord(input: ScheduledReportInput): ScheduledReportRecord {
  let body = "{}";
  try {
    body = JSON.stringify(input.body ?? {});
  } catch {
    body = "{}";
  }
  if (body.length > SCHEDULED_REPORT_MAX_BODY_CHARS) {
    body = body.slice(0, SCHEDULED_REPORT_MAX_BODY_CHARS);
  }
  return {
    id: crypto.randomUUID(),
    runId: input.runId,
    generationId: input.generationId,
    title: input.title,
    source: input.source,
    summary: input.summary,
    body,
    createdAt: input.createdAt ?? new Date().toISOString(),
  };
}

export interface CanonicalStoreResult {
  /** mas_reports row id (new or pre-existing). */
  reportId: string;
  /** True when this call created the row; false on idempotent dedupe. */
  created: boolean;
}

/**
 * Issue #308: THE single generate→store seam. The generator stores the
 * canonical report copy at generation time; every delivery channel reads
 * it back. Idempotent on input.generationId: when a row with that
 * generation id already exists, it is returned untouched (no duplicate,
 * no rewrite). SELECT-then-INSERT keeps MockSqlStorage compatible
 * (it does not parse INSERT OR REPLACE).
 *
 * Never throws: returns null on bad input or SQL errors so generation
 * and delivery are never broken by the store.
 */
/** The mas_reports row id already stored for a generation id, or "". */
function existingReportIdForGeneration(
  sql: SqlStorage,
  generationId: string
): string {
  const existing = Array.from(
    sql.exec(
      `SELECT id FROM ${SCHEDULED_REPORTS_TABLE} WHERE generation_id = ? LIMIT 1`,
      generationId
    )
  ) as Array<{ id?: unknown }>;
  return existing[0] ? String(existing[0].id ?? "") : "";
}

/**
 * Issue #1169 S4-1: the full row behind an existing report id, for the
 * redelivery index hook (a redelivery re-upserts the same vector id, so
 * the hook needs the stored title/source/summary/body, not the caller's
 * possibly-partial input). Null when the row cannot be loaded.
 */
function existingReportRowForId(
  sql: SqlStorage,
  id: string
): {
  title: string;
  source: string;
  summary: string;
  body: string;
  bodyR2Key: string | null;
} | null {
  try {
    const rows = Array.from(
      sql.exec(
        `SELECT title, source, summary, body, body_r2_key FROM ${SCHEDULED_REPORTS_TABLE} WHERE id = ? LIMIT 1`,
        id
      )
    ) as Array<Record<string, unknown>>;
    const row = rows[0];
    if (!row) return null;
    return {
      title: typeof row.title === "string" ? row.title : "",
      source: typeof row.source === "string" ? row.source : "",
      summary: typeof row.summary === "string" ? row.summary : "",
      body: typeof row.body === "string" ? row.body : "",
      bodyR2Key: typeof row.body_r2_key === "string" ? row.body_r2_key : null,
    };
  } catch {
    return null;
  }
}

function generationIdOf(input: ScheduledReportInput): string | null {
  return typeof input.generationId === "string" && input.generationId
    ? input.generationId
    : null;
}

function reportOwnerOf(input: ScheduledReportInput): string {
  return typeof input.userLogin === "string" && input.userLogin
    ? input.userLogin
    : "default";
}

/**
 * The one INSERT both store seams share (single line — MockSqlStorage's
 * INSERT regex has no dotAll flag). Issue #338: when bodyR2Key is set the
 * body column stores "" and the pointer names the R2 object holding the
 * body; otherwise the body is inline and the pointer is NULL.
 */
function insertScheduledReportRow(
  sql: SqlStorage,
  rec: ScheduledReportRecord,
  generationId: string | null,
  owner: string,
  bodyR2Key: string | null
): void {
  sql.exec(
    `INSERT INTO ${SCHEDULED_REPORTS_TABLE} (id, run_id, title, source, summary, body, created_at, generation_id, user_login, body_r2_key) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    rec.id,
    rec.runId,
    rec.title,
    rec.source,
    rec.summary,
    bodyR2Key ? "" : rec.body,
    rec.createdAt,
    generationId,
    owner,
    bodyR2Key
  );
}

/**
 * Issue #1169 S4-1: the optional env a caller passes when it has the
 * AI/Vectorize bindings — the seam then fires the index hook after a
 * successful store (fresh or redelivery). Callers without bindings omit
 * it; the hook is a silent no-op and those rows are covered by the
 * backfill route instead. The seam stays SYNC: the hook is
 * fire-and-forget (`void`), mirroring researchPublish's call.
 */
export function storeReportAtGeneration(
  sql: SqlStorage,
  input: ScheduledReportInput,
  env?: IndexEnv
): CanonicalStoreResult | null {
  try {
    if (!input || typeof input.runId !== "string" || !input.runId) return null;
    ensureScheduledReportsTable(sql);
    const generationId = generationIdOf(input);
    if (generationId) {
      const id = existingReportIdForGeneration(sql, generationId);
      if (id) {
        const row = existingReportRowForId(sql, id);
        if (row) {
          void indexCanonicalReport(env, {
            reportId: id,
            title: row.title,
            source: row.source,
            summary: row.summary,
            body: row.body,
            bodyR2Key: row.bodyR2Key,
          });
        }
        return { reportId: id, created: false };
      }
    }
    const rec = toScheduledReportRecord(input);
    insertScheduledReportRow(sql, rec, generationId, reportOwnerOf(input), null);
    void indexCanonicalReport(env, {
      reportId: rec.id,
      title: rec.title,
      source: rec.source,
      summary: rec.summary,
      body: rec.body,
      bodyR2Key: null,
    });
    return { reportId: rec.id, created: true };
  } catch (err) {
    // Issue #876: never silent. The caller (#835's null check) can only
    // say THAT the store failed; the worker log must say WHY.
    console.error(
      `[scheduledReports] storeReportAtGeneration failed for run ${typeof input?.runId === "string" ? input.runId : "?"}: ${err instanceof Error ? err.message : String(err)}`,
      err
    );
    return null;
  }
}

/**
 * Issue #338 S2: the R2 write path. Same contract as
 * storeReportAtGeneration (idempotent on generation id, never throws),
 * plus: when `env.REPORTS_BUCKET` is bound, the canonical body is put to
 * R2 at reports/<reportId>.json BEFORE the row insert, and the row keeps
 * only the body_r2_key pointer (body column ""). The dedupe check runs
 * first, so a re-delivery never rewrites the R2 object. When the bucket
 * is unbound — or the put fails — the write falls back to the exact
 * legacy inline shape: a report is never lost to the storage flip.
 */
export async function storeReportAtGenerationWithR2(
  sql: SqlStorage,
  env: { REPORTS_BUCKET?: R2Bucket; AI?: any; VECTOR_MEMORY?: any },
  input: ScheduledReportInput
): Promise<CanonicalStoreResult | null> {
  try {
    if (!input || typeof input.runId !== "string" || !input.runId) return null;
    ensureScheduledReportsTable(sql);
    const generationId = generationIdOf(input);
    if (generationId) {
      const id = existingReportIdForGeneration(sql, generationId);
      if (id) {
        const row = existingReportRowForId(sql, id);
        if (row) {
          void indexCanonicalReport(env, {
            reportId: id,
            title: row.title,
            source: row.source,
            summary: row.summary,
            body: row.body,
            bodyR2Key: row.bodyR2Key,
          });
        }
        return { reportId: id, created: false };
      }
    }
    const rec = toScheduledReportRecord(input);
    let bodyR2Key: string | null = null;
    const bucket = env?.REPORTS_BUCKET;
    if (bucket) {
      const key = reportBodyR2Key(rec.id);
      try {
        await bucket.put(key, rec.body, {
          httpMetadata: { contentType: "application/json" },
        });
        bodyR2Key = key;
      } catch (err) {
        console.error(
          `[scheduledReports] storeReportAtGenerationWithR2: R2 body put failed for report ${rec.id}; storing inline instead: ${err instanceof Error ? err.message : String(err)}`,
          err
        );
      }
    }
    insertScheduledReportRow(sql, rec, generationId, reportOwnerOf(input), bodyR2Key);
    void indexCanonicalReport(env, {
      reportId: rec.id,
      title: rec.title,
      source: rec.source,
      summary: rec.summary,
      body: bodyR2Key ? "" : rec.body,
      bodyR2Key,
    });
    return { reportId: rec.id, created: true };
  } catch (err) {
    console.error(
      `[scheduledReports] storeReportAtGenerationWithR2 failed for run ${typeof input?.runId === "string" ? input.runId : "?"}: ${err instanceof Error ? err.message : String(err)}`,
      err
    );
    return null;
  }
}

/**
 * Issue #338 S3: the coupled delete — the ONLY way a mas_reports row may
 * be removed. The design requires the R2 body object to be deleted in
 * the same scope as the row, or every deletion strands an object. The
 * object delete runs first and is best-effort: if it fails (or no bucket
 * is bound) the failure is logged and the row is still deleted — a
 * stranded object is inert and is the orphan sweep's job (the design's
 * named follow-up), while a stranded ROW pointing at a deleted object
 * would break reads. mas_reports has no pruning today (retention
 * decision #786: KEEP — pruning is a product decision); this primitive
 * exists so that any future deletion path is coupled by construction.
 * Never throws; returns true when the row is gone.
 */
export async function deleteCanonicalReport(
  sql: SqlStorage,
  env: { REPORTS_BUCKET?: R2Bucket },
  reportId: string
): Promise<boolean> {
  try {
    if (!reportId) return false;
    ensureScheduledReportsTable(sql);
    const hit = getCanonicalReport(sql, reportId);
    if (!hit) return false;
    if (hit.bodyR2Key) {
      const bucket = env?.REPORTS_BUCKET;
      if (bucket) {
        try {
          await bucket.delete(hit.bodyR2Key);
        } catch (err) {
          console.error(
            `[scheduledReports] deleteCanonicalReport: R2 delete failed for report ${reportId} (key ${hit.bodyR2Key}); deleting the row anyway — the orphan sweep owns the stranded object: ${err instanceof Error ? err.message : String(err)}`,
            err
          );
        }
      } else {
        console.error(
          `[scheduledReports] deleteCanonicalReport: no REPORTS_BUCKET bound; deleting row ${reportId} strands its R2 object (key ${hit.bodyR2Key}) for the orphan sweep`
        );
      }
    }
    sql.exec(
      `DELETE FROM ${SCHEDULED_REPORTS_TABLE} WHERE id = ?`,
      reportId
    );
    return true;
  } catch (err) {
    console.error(
      `[scheduledReports] deleteCanonicalReport failed for report ${reportId}: ${err instanceof Error ? err.message : String(err)}`,
      err
    );
    return false;
  }
}

/**
 * Issue #338 S4: resolve with lazy backfill — the design's migration
 * path ("NULL → serve inline, optionally backfill on first read"). A
 * pointer row resolves exactly as resolveCanonicalReportBody. An inline
 * row served while REPORTS_BUCKET is bound is first copied to R2 and
 * its row rewritten to the pointer shape (body "", body_r2_key set,
 * guarded on the pointer still being NULL so a racing writer wins);
 * the inline body is returned either way. Backfill is best-effort: any
 * failure is logged and the row stays inline for the next read — a
 * read never fails because the migration hiccuped.
 */
export async function resolveCanonicalReportBodyWithBackfill(
  sql: SqlStorage,
  env: { REPORTS_BUCKET?: R2Bucket },
  hit: ScheduledReportHit
): Promise<string | null> {
  if (hit.bodyR2Key) return resolveCanonicalReportBody(env, hit);
  const bucket = env?.REPORTS_BUCKET;
  if (!bucket || !hit.body) return hit.body;
  const key = reportBodyR2Key(hit.id);
  try {
    await bucket.put(key, hit.body, {
      httpMetadata: { contentType: "application/json" },
    });
    ensureScheduledReportsTable(sql);
    sql.exec(
      `UPDATE ${SCHEDULED_REPORTS_TABLE} SET body_r2_key = ?, body = '' WHERE id = ? AND body_r2_key IS NULL`,
      key,
      hit.id
    );
  } catch (err) {
    console.error(
      `[scheduledReports] resolveCanonicalReportBodyWithBackfill: backfill failed for report ${hit.id}; serving inline (retried on next read): ${err instanceof Error ? err.message : String(err)}`,
      err
    );
  }
  return hit.body;
}

/**
 * Issue #338 S2: resolve a stored report's canonical body. A null pointer
 * means the body is inline — return it as-is. A set pointer reads the R2
 * object; a missing bucket, missing object, or read error resolves to
 * null so callers fail closed (delivery reports "missing") instead of
 * delivering an empty body.
 */
export async function resolveCanonicalReportBody(
  env: { REPORTS_BUCKET?: R2Bucket },
  hit: ScheduledReportHit
): Promise<string | null> {
  if (!hit.bodyR2Key) return hit.body;
  const bucket = env?.REPORTS_BUCKET;
  if (!bucket) return null;
  try {
    const obj = await bucket.get(hit.bodyR2Key);
    if (!obj) return null;
    return await obj.text();
  } catch (err) {
    // Issue #876 doctrine: never silent — a failed body read is a
    // storage symptom the worker log must show.
    console.error(
      `[scheduledReports] resolveCanonicalReportBody failed for report ${hit.id} (key ${hit.bodyR2Key}): ${err instanceof Error ? err.message : String(err)}`,
      err
    );
    return null;
  }
}

/** Read back the canonical stored copy for delivery. Never throws. */
export function getCanonicalReport(
  sql: SqlStorage,
  reportId: string
): ScheduledReportHit | null {
  try {
    if (!reportId) return null;
    ensureScheduledReportsTable(sql);
    const rows = Array.from(
      sql.exec(
        `SELECT id, run_id, title, source, summary, body, created_at, body_r2_key FROM ${SCHEDULED_REPORTS_TABLE} WHERE id = ? LIMIT 1`,
        reportId
      )
    ) as Array<Record<string, unknown>>;
    const r = rows[0];
    if (!r) return null;
    return scheduledReportHitFromRow(r);
  } catch {
    return null;
  }
}

/** SHA-256 hex of text — content-hash generation ids for client reports. */
export async function sha256Hex(text: string): Promise<string> {
  const digest = await crypto.subtle.digest(
    "SHA-256",
    new TextEncoder().encode(text)
  );
  return Array.from(new Uint8Array(digest))
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
}

/**
 * Canonical JSON body for a research-report email dispatch. Field order
 * is fixed so the stored bytes are deterministic — what a channel
 * delivers equals the stored body byte-for-byte.
 */
export function canonicalResearchEmailBody(input: {
  title: string;
  fileName: string;
  attachmentBase64: string;
}): string {
  return JSON.stringify({
    title: String(input.title ?? ""),
    fileName: String(input.fileName ?? ""),
    attachmentBase64: String(input.attachmentBase64 ?? ""),
  });
}

/**
 * Canonical JSON body for a research-report webhook dispatch. Fixed
 * field order for byte-identical re-delivery from the stored copy.
 */
export function canonicalResearchWebhookBody(input: {
  title: string;
  query: string;
  sheets: Array<{ name: string; rows: Array<Record<string, unknown>> }>;
}): string {
  return JSON.stringify({
    title: String(input.title ?? ""),
    query: String(input.query ?? ""),
    sheets: Array.isArray(input.sheets) ? input.sheets : [],
  });
}

/** Parse a stored research-report body back into delivery fields. */
export function parseResearchReportBody(bodyJson: string): {
  title: string;
  fileName: string;
  attachmentBase64: string;
  query: string;
  sheets: Array<{ name: string; rows: Array<Record<string, unknown>> }>;
} | null {
  try {
    const parsed = JSON.parse(String(bodyJson)) as Record<string, unknown>;
    if (!parsed || typeof parsed !== "object") return null;
    const sheets = Array.isArray(parsed.sheets) ? parsed.sheets : [];
    return {
      title: String(parsed.title ?? ""),
      fileName: String(parsed.fileName ?? ""),
      attachmentBase64: String(parsed.attachmentBase64 ?? ""),
      query: String(parsed.query ?? ""),
      sheets: sheets as Array<{
        name: string;
        rows: Array<Record<string, unknown>>;
      }>,
    };
  } catch {
    return null;
  }
}

/** Persist via raw SQL (for call sites holding SqlStorage). Never throws. */
export function persistScheduledReportSql(
  sql: SqlStorage,
  input: ScheduledReportInput
): string | null {
  try {
    ensureScheduledReportsTable(sql);
    const rec = toScheduledReportRecord(input);
    // Issue #901: INSERT must include generation_id and user_login.
    // The table has these columns (via ensureColumn), but the old INSERT
    // omitted them, causing the write to fail on strict schemas.
    sql.exec(
      `INSERT INTO ${SCHEDULED_REPORTS_TABLE} (id, run_id, title, source, summary, body, created_at, generation_id, user_login) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      rec.id,
      rec.runId,
      rec.title,
      rec.source,
      rec.summary,
      rec.body,
      rec.createdAt,
      rec.generationId ?? null,
      input.userLogin ?? "default"
    );
    return rec.id;
  } catch (err) {
    // Issue #876: never silent. This bare catch is what hid the production
    // write failure behind "persistScheduledReportSql returned null" —
    // the underlying SQL error is logged here before returning null.
    console.error(
      `[scheduledReports] persistScheduledReportSql failed for run ${typeof input?.runId === "string" ? input.runId : "?"}: ${err instanceof Error ? err.message : String(err)}`,
      err
    );
    return null;
  }
}

export interface ScheduledReportHit {
  id: string;
  runId: string;
  title: string;
  source: string;
  summary: string;
  body: string;
  createdAt: string;
  /**
   * Issue #338: R2 pointer for the canonical body, or null when the body
   * is stored inline in `body` (NULL = inline, per the accepted design).
   * S1 plumbing only — readers surface the pointer; S2 resolves it.
   */
  bodyR2Key: string | null;
}

/**
 * Issue #338: the R2 object key for a report's canonical body, per the
 * accepted design — `reports/<reportId>.json` in the REPORTS_BUCKET
 * bucket (the `screener` bucket provisioned for #605). Content-addressed
 * by report id; bodies are immutable (regeneration = a new report id).
 */
export function reportBodyR2Key(reportId: string): string {
  return `reports/${reportId}.json`;
}

/** Map one mas_reports row to a hit, tolerating pre-#338 rows (no key). */
function scheduledReportHitFromRow(
  r: Record<string, unknown>
): ScheduledReportHit {
  const key = r.body_r2_key;
  return {
    id: String(r.id ?? ""),
    runId: String(r.run_id ?? ""),
    title: String(r.title ?? ""),
    source: String(r.source ?? ""),
    summary: String(r.summary ?? ""),
    body: String(r.body ?? ""),
    createdAt: String(r.created_at ?? ""),
    bodyR2Key: typeof key === "string" && key ? key : null,
  };
}

/**
 * Token-based search over stored reports, newest first. Tokens shorter
 * than 3 chars are ignored to keep the LIKE scan cheap. Never throws.
 */
export function searchScheduledReports(
  sql: SqlStorage,
  query: string,
  limit: number = SCHEDULED_REPORT_DEFAULT_LIMIT,
  opts?: { userLogin?: string }
): ScheduledReportHit[] {
  try {
    ensureScheduledReportsTable(sql);
    const tokens = query
      .toLowerCase()
      .split(/\s+/)
      .filter((t) => t.length > 2)
      .slice(0, 8);
    if (tokens.length === 0) return [];
    const clause = tokens
      .map(
        () =>
          `(LOWER(title) LIKE ? OR LOWER(summary) LIKE ? OR LOWER(body) LIKE ?)`
      )
      .join(" OR ");
    const params: unknown[] = [];
    for (const t of tokens) {
      const like = `%${t}%`;
      params.push(like, like, like);
    }
    // #584 EP-003: tenant scoping. When the caller knows the user, filter
    // strictly. When unknown (undefined), preserve legacy behavior (all
    // rows): the deployment's identity strings are not yet unified
    // ("default" vs the legacy shared login vs session ids), so a strict default
    // would hide a user's own rows. See #488.
    const owner =
      opts?.userLogin && typeof opts.userLogin === "string"
        ? opts.userLogin
        : undefined;
    const capped = Math.max(1, Math.min(Math.floor(limit) || SCHEDULED_REPORT_DEFAULT_LIMIT, 25));
    const ownerClause = owner ? `user_login = ? AND ` : "";
    const ownerParams: unknown[] = owner ? [owner] : [];
    const rows = Array.from(
      sql.exec(
        `SELECT id, run_id, title, source, summary, body, created_at, body_r2_key FROM ${SCHEDULED_REPORTS_TABLE} WHERE ${ownerClause}(${clause}) ORDER BY created_at DESC LIMIT ?`,
        ...ownerParams,
        ...params,
        capped
      )
    ) as Array<Record<string, unknown>>;
    return rows.map(scheduledReportHitFromRow);
  } catch {
    return [];
  }
}

/**
 * #584 EP-003: user-scoped report listing, newest first. Extracted from the
 * /reports route so the scoping is tested in one place.
 */
export function listScheduledReports(
  sql: SqlStorage,
  opts?: { userLogin?: string; sourceFilter?: string; limit?: number }
): ScheduledReportHit[] {
  try {
    ensureScheduledReportsTable(sql);
    // #584 EP-003: strict filter when the caller knows the user; legacy
    // unfiltered behavior when unknown (identity strings not yet unified).
    const owner =
      opts?.userLogin && typeof opts.userLogin === "string"
        ? opts.userLogin
        : undefined;
    const limit = Math.max(
      1,
      Math.min(Math.floor(opts?.limit ?? 50) || 50, 100)
    );
    let q = `SELECT id, run_id, title, source, summary, body, created_at, body_r2_key FROM ${SCHEDULED_REPORTS_TABLE}`;
    const params: unknown[] = [];
    const wheres: string[] = [];
    if (owner) {
      wheres.push(`user_login = ?`);
      params.push(owner);
    }
    if (opts?.sourceFilter) {
      wheres.push(`source = ?`);
      params.push(opts.sourceFilter);
    }
    if (wheres.length > 0) q += ` WHERE ` + wheres.join(" AND ");
    q += ` ORDER BY created_at DESC LIMIT ?`;
    params.push(limit);
    const rows = Array.from(sql.exec(q, ...params)) as Array<
      Record<string, unknown>
    >;
    return rows.map(scheduledReportHitFromRow);
  } catch {
    return [];
  }
}

/**
 * Issue #339: fetch one stored report by id for the Reports-tab detail
 * view. Owner scoping matches the list (#584 EP-003): strict when the
 * caller login is known, legacy unfiltered when it is not. Returns null
 * when the report does not exist (or is not the caller's). Never throws.
 */
export function getScheduledReportById(
  sql: SqlStorage,
  reportId: string,
  opts?: { userLogin?: string }
): ScheduledReportHit | null {
  try {
    if (!reportId || typeof reportId !== "string") return null;
    ensureScheduledReportsTable(sql);
    const owner =
      opts?.userLogin && typeof opts.userLogin === "string"
        ? opts.userLogin
        : undefined;
    let q = `SELECT id, run_id, title, source, summary, body, created_at, body_r2_key FROM ${SCHEDULED_REPORTS_TABLE} WHERE id = ?`;
    const params: unknown[] = [reportId];
    if (owner) {
      q += ` AND user_login = ?`;
      params.push(owner);
    }
    q += ` LIMIT 1`;
    const rows = Array.from(sql.exec(q, ...params)) as Array<
      Record<string, unknown>
    >;
    if (rows.length === 0) return null;
    return scheduledReportHitFromRow(rows[0]);
  } catch {
    return null;
  }
}

/* ------------------------------------------------------------------ */
/* #584 EP-009: usage metering                                          */
/*                                                                      */
/* Issue #792 determination (RSI-Data C9 — parallel persistence         */
/* idioms): usage_events is ACCEPTED as the metering store of record,   */
/* a separate concern from mas_events — not a second copy of it.        */
/* mas_events is the session-scoped audit/observability log (owner:     */
/* OrchestratorAgent.recordAudit, #270; session_id / type / agent /     */
/* payload). Usage metering is tenant-scoped instead: WHO (user_login), */
/* WHAT TASK (run_id), WHAT KIND (category), with an index on           */
/* (user_login, created_at) for per-tenant listing. mas_events cannot   */
/* carry this data with its existing shape — no user_login/run_id       */
/* columns, no tenant index, and its session_id is the orchestrator     */
/* instance's session key, not a tenant identity. Writers: the          */
/* orchestrator meters completed research runs (category                */
/* "research_run") and ResearchAgent meters evaluations                 */
/* ("research_evaluation"), each into its OWN DO's database through     */
/* this module — so no single database holds a tenant's whole usage     */
/* picture, and no production reader consumes the rows yet              */
/* (listUsageEvents is exercised by tests only). Both facts are the     */
/* known price of the split; the first production usage/billing reader  */
/* must solve the placement question, and that is the trigger to        */
/* re-open consolidation. Do not add a third event log meanwhile.       */
/*                                                                      */
/* Issue #786 retention decision: usage_events is PRUNE-CLASS at 365d,   */
/* recorded in src/security/storageRetention.ts (the retention record   */
/* for every mas_* table). Implementation is deferred to the first      */
/* production reader: rows are split across two DOs' databases (this     */
/* module writes into the orchestrator's and ResearchAgent's own         */
/* storage), so a retention pass on one instance cannot prune the        */
/* other copy, and a partial prune would misstate tenant totals. Until   */
/* then the bound is one small row per research run/evaluation.          */
/* ------------------------------------------------------------------ */

export const USAGE_EVENTS_TABLE = "usage_events";

export interface UsageEventInput {
  /** Tenant identity (user login). */
  userLogin: string;
  /** Task identity, e.g. the research run id. */
  runId: string;
  /** Billable category, e.g. "research_run" | "research_evaluation". */
  category: string;
  /** Optional detail payload (JSON-serializable). */
  detail?: unknown;
}

export interface UsageEvent {
  id: string;
  userLogin: string;
  runId: string;
  category: string;
  createdAt: string;
}

/** Idempotent DDL for usage_events. Never throws. */
export function ensureUsageEventsTable(sql: SqlStorage): void {
  try {
    sql.exec(`CREATE TABLE IF NOT EXISTS ${USAGE_EVENTS_TABLE} (
      id TEXT PRIMARY KEY,
      user_login TEXT NOT NULL,
      run_id TEXT NOT NULL,
      category TEXT NOT NULL,
      created_at TEXT NOT NULL,
      detail_json TEXT
    )`);
    sql.exec(
      `CREATE INDEX IF NOT EXISTS idx_usage_events_user ON ${USAGE_EVENTS_TABLE} (user_login, created_at DESC)`
    );
  } catch (err) {
    // Fails closed; callers treat a missing table as no events. Issue
    // #876: logged, not silent (same persistence-seam rule as mas_reports).
    console.error(
      `[scheduledReports] ensureUsageEventsTable failed: ${err instanceof Error ? err.message : String(err)}`,
      err
    );
  }
}

/**
 * Record one metered consumption event, attributed to tenant + task.
 * Never throws — metering must not break the metered operation.
 */
export function recordUsageEvent(
  sql: SqlStorage,
  input: UsageEventInput
): string | null {
  try {
    if (!input || !input.userLogin || !input.runId || !input.category)
      return null;
    ensureUsageEventsTable(sql);
    const id = `use_${Date.now().toString(36)}_${Math.random()
      .toString(36)
      .slice(2, 8)}`;
    sql.exec(
      `INSERT INTO ${USAGE_EVENTS_TABLE} (id, user_login, run_id, category, created_at, detail_json) VALUES (?, ?, ?, ?, ?, ?)`,
      id,
      input.userLogin,
      input.runId,
      input.category,
      new Date().toISOString(),
      input.detail === undefined ? null : JSON.stringify(input.detail)
    );
    return id;
  } catch (err) {
    // Issue #876: never silent at a persistence seam — metering failures
    // are logged before the never-throws null is returned.
    console.error(
      `[scheduledReports] recordUsageEvent failed for run ${typeof input?.runId === "string" ? input.runId : "?"}: ${err instanceof Error ? err.message : String(err)}`,
      err
    );
    return null;
  }
}

/** List usage events for one tenant, newest first. Never throws. */
export function listUsageEvents(
  sql: SqlStorage,
  userLogin: string,
  limit = 100
): UsageEvent[] {
  try {
    if (!userLogin) return [];
    ensureUsageEventsTable(sql);
    const capped = Math.max(1, Math.min(Math.floor(limit) || 100, 500));
    const rows = Array.from(
      sql.exec(
        `SELECT id, user_login, run_id, category, created_at FROM ${USAGE_EVENTS_TABLE} WHERE user_login = ? ORDER BY created_at DESC LIMIT ?`,
        userLogin,
        capped
      )
    ) as Array<Record<string, unknown>>;
    return rows.map((r) => ({
      id: String(r.id ?? ""),
      userLogin: String(r.user_login ?? ""),
      runId: String(r.run_id ?? ""),
      category: String(r.category ?? ""),
      createdAt: String(r.created_at ?? ""),
    }));
  } catch {
    return [];
  }
}

/**
 * #638: resolve the generated PDF download URL for a stored report.
 * The PDF bytes live in ScreenerAgent storage behind the report.pdf
 * endpoints (#269/#361); the canonical body carries either a ready
 * reportUrl or the pdfKey it was stored under. Prefers a relative
 * key-based URL (valid on any host) and falls back to the stored
 * absolute reportUrl. Returns undefined when the report has no PDF.
 * Never throws — a malformed body simply has no PDF.
 */
export function scheduledReportPdfUrl(source: string, body: unknown): string | undefined {
  try {
    const parsed: any = typeof body === "string" ? JSON.parse(body || "{}") : (body ?? {});
    const pdfKey = parsed?.pdfKey ?? parsed?.result?.pdfKey;
    if (typeof pdfKey === "string" && pdfKey) {
      if (source === "screener") return `/api/screener/report.pdf?key=${encodeURIComponent(pdfKey)}`;
      if (source === "options_scanner") return `/api/options/report.pdf?key=${encodeURIComponent(pdfKey)}`;
      // Issue #1335: goal-screen PDFs serve from the goal-screen route.
      if (source === "goal_screen")
        return `/api/screening/goal-screen/report.pdf?key=${encodeURIComponent(pdfKey)}`;
    }
    const stored = parsed?.reportUrl ?? parsed?.result?.reportUrl;
    return typeof stored === "string" && stored ? stored : undefined;
  } catch {
    return undefined;
  }
}
